// Signature roles in agreements generated by Agreement Studio: the draft's parties tell the detector which
// signature block is the workspace's (firm) and which is the client's. Without parties, or when the workspace's
// name doesn't pick out exactly one party, detection is the same as for any upload.
import { describe, expect, it } from "vitest";
import { generateAgreement, type GenerateInput } from "@/lib/m23/m23-generate";
import { renderDocument } from "@/lib/m23/doc-output";
import { extractPdf } from "@/lib/pdf/extract";
import { detectFields, knownSigners, type DetectOptions } from "@/lib/detect";
import type { Field } from "@/lib/fields";

const WS = { firmName: "Northwind Advisory, LLC", workspaceNames: ["Northwind"] };
const NDA_TERMS = { startDate: "2027-02-01", confidentialityYears: 3, governingLaw: "Example State" };

async function detect(input: GenerateInput, opts: DetectOptions) {
  const r = await generateAgreement(input);
  if (r.status !== "ok") throw new Error(JSON.stringify(r));
  const ex = await extractPdf((await renderDocument(r.draft, "pdf")).bytes);
  return { det: detectFields(ex, opts), parties: r.draft.parties };
}

/** Role of each signature (and the date in its block), keyed by the "Signed for ..." heading it sits under. */
const sigRoles = (fields: Field[]) => fields.filter((f) => f.type === "signature").map((f) => f.role);
const shape = (fields: Field[]) => fields.map((f) => ({ type: f.type, role: f.role, page: f.page, x: f.x, y: f.y, w: f.w, h: f.h, prefillKey: f.prefillKey }));

describe("knownSigners", () => {
  const p = (a: string, b: string) => [{ role: "Disclosing Party", name: a }, { role: "Receiving Party", name: b }];
  it("matches the workspace's legal or display name, ignoring case and punctuation", () => {
    expect(knownSigners(p("Northwind Advisory LLC", "Acme Widgets Inc"), ["Northwind Advisory, LLC"])?.firm.name).toBe("Northwind Advisory LLC");
    expect(knownSigners(p("Acme Widgets Inc", "NORTHWIND ADVISORY, L.L.C."), ["Northwind Advisory LLC"])?.client.name).toBe("Acme Widgets Inc");
    expect(knownSigners(p("Acme Widgets Inc", "Northwind"), ["Northwind Advisory, LLC", "Northwind"])?.firm.role).toBe("Receiving Party");
  });
  it("returns null when neither, or both, parties match, or when it can't tell them apart", () => {
    expect(knownSigners(p("Acme Widgets Inc", "Example Labs"), ["Northwind Advisory, LLC", "Northwind"])).toBeNull();
    // a party name that merely contains the workspace's name is not the workspace
    expect(knownSigners(p("Northwind Advisory LLC Holdings", "Acme Widgets Inc"), ["Northwind Advisory, LLC"])).toBeNull();
    expect(knownSigners(p("Northwind", "Northwind Advisory LLC"), ["Northwind Advisory, LLC", "Northwind"])).toBeNull();
    expect(knownSigners(p("Northwind Advisory LLC", "northwind advisory, llc"), ["Northwind Advisory, LLC"])).toBeNull();
    expect(knownSigners([{ role: "Disclosing Party", name: "Northwind Advisory LLC" }], ["Northwind Advisory, LLC"])).toBeNull();
    expect(knownSigners(undefined, ["Northwind Advisory, LLC"])).toBeNull();
    expect(knownSigners(p("Northwind Advisory LLC", "Acme Widgets Inc"), [undefined, ""])).toBeNull();
  });
});

describe("Studio NDA signature blocks", () => {
  it("without parties (an ordinary upload) both blocks go to the firm, as before", async () => {
    const { det } = await detect({ kind: "nda", parties: [{ role: "Disclosing Party", name: "Northwind Advisory LLC" }, { role: "Receiving Party", name: "Acme Widgets Inc" }], terms: NDA_TERMS }, WS);
    expect(sigRoles(det.fields)).toEqual(["firm", "firm"]);
    expect(det.warnings).toContain("No client signature line was found.");
  });

  for (const firmRole of ["Disclosing Party", "Receiving Party"]) {
    it(`workspace as the ${firmRole}: its block is the firm's, the other party's is the client's`, async () => {
      const parties = ["Disclosing Party", "Receiving Party"].map((role) => ({ role, name: role === firmRole ? "Northwind Advisory LLC" : "Acme Widgets Inc" }));
      const { det, parties: drafted } = await detect({ kind: "nda", parties, terms: NDA_TERMS }, { ...WS, parties });
      const sigs = det.fields.filter((f) => f.type === "signature");
      expect(sigs).toHaveLength(2);
      // blocks print in the template's role order: Disclosing Party first
      expect(sigRoles(det.fields)).toEqual(firmRole === "Disclosing Party" ? ["firm", "client"] : ["client", "firm"]);
      for (const f of det.fields.filter((x) => x.type === "date")) expect(f.role).toBe(sigs.find((s) => Math.abs(s.y - f.y) < 80)!.role);
      expect(det.warnings).not.toContain("No client signature line was found.");
      expect(det.warnings).not.toContain("No signature line for your firm was found. Your acceptance will still be recorded on the certificate.");
      // the order the parties are passed in doesn't matter
      const reversed = await detect({ kind: "nda", parties, terms: NDA_TERMS }, { ...WS, parties: [...drafted].reverse() });
      expect(shape(reversed.det.fields)).toEqual(shape(det.fields));
    });
  }

  it("matches the display name when the party is named that way", async () => {
    const parties = [{ role: "Disclosing Party", name: "Acme Widgets Inc" }, { role: "Receiving Party", name: "Northwind" }];
    const { det } = await detect({ kind: "nda", parties, terms: NDA_TERMS }, { ...WS, parties });
    expect(sigRoles(det.fields)).toEqual(["client", "firm"]);
  });

  it("ambiguous names fall back to ordinary detection, unchanged", async () => {
    const neither = [{ role: "Disclosing Party", name: "Example Labs" }, { role: "Receiving Party", name: "Acme Widgets Inc" }];
    const both = [{ role: "Disclosing Party", name: "Northwind Advisory LLC" }, { role: "Receiving Party", name: "Northwind" }];
    for (const parties of [neither, both]) {
      const plain = await detect({ kind: "nda", parties, terms: NDA_TERMS }, WS);
      const withParties = await detect({ kind: "nda", parties, terms: NDA_TERMS }, { ...WS, parties });
      expect(withParties.det).toEqual(plain.det);
    }
  });
});

describe("Studio services agreement", () => {
  const parties = [{ role: "Provider", name: "Northwind Advisory LLC" }, { role: "Client", name: "Example Widgets Ltd" }];
  const input: GenerateInput = { kind: "services", parties, terms: { fee: "$5,000", paymentDays: 30, startDate: "2027-03-01", noticeDays: 14, governingLaw: "Example State" } };
  it("gets the same fields and roles with or without parties", async () => {
    const plain = await detect(input, WS);
    const withParties = await detect(input, { ...WS, parties });
    expect(sigRoles(plain.det.fields)).toEqual(["firm", "client"]);
    expect(shape(withParties.det.fields)).toEqual(shape(plain.det.fields));
    expect(withParties.det.warnings).toEqual(plain.det.warnings);
  });
});

describe("every Studio kind, workspace on either side", () => {
  const base = { startDate: "2027-03-01", noticeDays: 21, governingLaw: "Example State", fee: "USD 4,800" };
  const KINDS: [GenerateInput["kind"], [string, string], Record<string, string | number>][] = [
    ["nda", ["Disclosing Party", "Receiving Party"], NDA_TERMS],
    ["services", ["Provider", "Client"], { ...base, paymentDays: 30 }],
    ["retainer", ["Firm", "Client"], { ...base, feePeriod: "month" }],
    ["engagement", ["Firm", "Client"], base],
    ["consulting", ["Consultant", "Client"], { ...base, ipOwner: "Client" }],
    ["licence", ["Licensor", "Licensee"], { ...base, licensedMaterial: "the Sample Analytics software", territory: "the United Kingdom", exclusivity: "non-exclusive", licensedUse: "use", licenceTransfer: "with written consent" }],
    ["lease", ["Landlord", "Tenant"], { propertyAddress: "1 Example Street, Testville", premisesUse: "residential use only", rentSchedule: "monthly, in advance, on the first day", subletting: "with written consent", rent: "$1,200", deposit: "$1,200", startDate: "2027-02-01", endDate: "2028-01-31", noticeDays: 60, governingLaw: "Example State" }],
  ];
  for (const [kind, roles, terms] of KINDS) {
    for (const side of [0, 1]) {
      it(`${kind}: workspace as the ${roles[side]}`, async () => {
        const parties = roles.map((role, i) => ({ role, name: i === side ? "Northwind Advisory LLC" : "Example Widgets Ltd" }));
        const { det } = await detect({ kind, parties, terms } as GenerateInput, { ...WS, parties });
        expect(sigRoles(det.fields)).toEqual(side === 0 ? ["firm", "client"] : ["client", "firm"]);
      });
    }
  }
});
